#include <string>
#include <vector>

class Solution {
public:
    bool canConvertString(std::string s, std::string t, int k) {
        if (s.size() != t.size()) return false;
        std::vector<int> counts(26, 0);
        for (size_t i = 0; i < s.size(); ++i) {
            int diff = (t[i] - s[i] + 26) % 26;
            if (diff > 0) {
                long long needed = (long long)diff + 26LL * counts[diff];
                if (needed > k) return false;
                counts[diff]++;
            }
        }
        return true;
    }
};

class Solution {
    public boolean canConvertString(String s, String t, int k) {
        if (s.length() != t.length()) return false;
        int[] counts = new int[26];
        for (int i = 0; i < s.length(); i++) {
            int diff = (t.charAt(i) - s.charAt(i) + 26) % 26;
            if (diff > 0) {
                long needed = (long) diff + 26L * counts[diff];
                if (needed > k) return false;
                counts[diff]++;
            }
        }
        return true;
    }
}

var canConvertString = function(s, t, k) {
    if (s.length !== t.length) return false;
    const counts = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        const diff = (t.charCodeAt(i) - s.charCodeAt(i) + 26) % 26;
        if (diff > 0) {
            const needed = diff + 26 * counts[diff];
            if (needed > k) return false;
            counts[diff]++;
        }
    }
    return true;
};
